var i=`1216-casado`;var n=`world-1216`;var a=`CR`;var o=`central-america-caribbean`;var s=4;var r=73;var d={en:`Casado`,ua:`Касадо`};var l={en:`Casado is a dish from Costa Rica featuring white rice, chicken thigh, tomato, yellow onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Касадо, страва кухні країни Коста-Рика з такими основними складниками: білий рис, куряче стегно, помідор, жовта цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var c=[{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 23 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 23 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:23,i:[[`white-rice`,330,`g`],[`water`,550,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 32 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 32 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:32,i:[[`chicken-thigh`,700,`g`],[`tomato`,200,`g`],[`yellow-onion`,130,`g`],[`garlic`,3,`clove`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`plantain`,420,`g`],[`canola-oil`,100,`ml`]]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`canned-black-beans`,350,`g`],[`lettuce`,130,`g`],[`avocado`,2,`pcs`]]}];var g={slug:i,id:n,country:`CR`,region:o,servings:4,minutes:73,title:d,text:l,steps:c};export{a as country,g as default,n as id,r as minutes,o as region,s as servings,i as slug,c as steps,l as text,d as title};